python -c "import joblib,numpy as np,pandas as pd; from sklearn.preprocessing import StandardScaler; from scipy.spatial.distance import cdist; t,p,X,m=joblib.load('nlo_features.joblib'); r,d,cv=joblib.load('nlo_models.joblib'); keys=['cat4','cat5','extra','laplace']; go=np.mean([d[('gap',k)]['oof'] for k in keys],axis=0); gp=np.mean([d[('gap',k)]['pool'] for k in keys],axis=0); so=np.mean([d[('logshg',k)]['oof'] for k in keys],axis=0); sp=np.mean([d[('logshg',k)]['pool'] for k in keys],axis=0); ge=t.band_gap.values-go; se=np.log1p(t.shg.values)-so; z=StandardScaler().fit_transform(X); dist=cdist(z[200:],z[:200],metric='cityblock')/X.shape[1]; sizes=m.formula[:200].map(m.formula[:200].value_counts()).values; rows=[]; ids=[37,50,51,52,57,76,77,78,81,83]; print('LOCAL NEIGHBOR RESIDUAL CHECK');
for i in ids:
 j=i-1; w=np.exp(-dist[j]*8)/sizes; w=w/w.sum(); eligible=(gp[j]+ge>=3); utility=np.maximum(0,np.expm1(sp[j]+np.clip(se,-1.5,1.5)))*eligible; rows.append([p.candidate_id[j],gp[j],np.expm1(sp[j]),sum(w*ge),sum(w*eligible),sum(w*utility)]); inds=np.argsort(dist[j])[:8]; print(p.candidate_id[j],[(str(t.formula[k]),round(dist[j,k],2),round(ge[k],2),round(se[k],2)) for k in inds]);
print(pd.DataFrame(rows,columns=['id','gap','shg','local_gap_bias','empirical_pass_fraction','empirical_score']).round(3).to_string(index=False))"

python -c "import pandas as pd; from pymatgen.io.vasp import Poscar; from pymatgen.symmetry.analyzer import SpacegroupAnalyzer; t=pd.read_csv('nlo_shg_eg_train.csv'); p=pd.read_csv('nlo_pool.csv'); assert t.shape[0]==200 and p.shape[0]==100; assert p.candidate_id.is_unique and not t.isna().any().any() and not p.isna().any().any(); ids=['c052','c051','c050','c081','c076']; print('Verified input counts, missing values, unique IDs, and selected structures:');
for cid in ids:
 r=p.set_index('candidate_id').loc[cid]; s=Poscar.from_str(r.poscar).structure; sg=SpacegroupAnalyzer(s,symprec=.01); print(cid,s.composition.reduced_formula,sg.get_space_group_symbol(),sg.get_space_group_number(),len(s))"

